/**
 * Registers the Angular service worker (ngsw-worker.js, generated by the
 * production build from frontend/ngsw-config.json) without
 * provideServiceWorker(), so @angular/service-worker adds nothing to the
 * initial bundle. There is no in-app update prompt: a new deploy is picked up
 * on a later page load. Cache rules live in ngsw-config.json; why they look
 * the way they do is in docs/CONSUMPTION_SURFACES.md「行動裝置閱讀出口（PWA）」.
 */
export const SW_SCRIPT = 'ngsw-worker.js';
/** Runtime config rendered at container start; cached network-first by the SW. */
export const RUNTIME_CONFIG = 'env.js';

export interface SwEnvironment {
  container: ServiceWorkerContainer | undefined;
  enabled: boolean;
  /** Re-requests env.js through the SW so its network-first cache is filled on
   * the very first visit (that page's own env.js load predates the SW). */
  warm: (url: string) => Promise<unknown>;
}

export async function registerServiceWorker(env: SwEnvironment): Promise<boolean> {
  const { container, enabled, warm } = env;
  if (!enabled || !container) return false;
  try {
    await container.register(SW_SCRIPT, { scope: './' });
  } catch {
    // Unsupported context (http, private mode quirks): the app works online.
    return false;
  }
  const warmConfig = () => void warm(RUNTIME_CONFIG).catch(() => undefined);
  if (container.controller) warmConfig();
  else container.addEventListener('controllerchange', warmConfig, { once: true });
  return true;
}

/** Called from main.ts after bootstrap; waits for `load` so the SW's prefetch
 * never competes with the first render. */
export function scheduleServiceWorker(enabled: boolean): void {
  if (typeof window === 'undefined' || typeof navigator === 'undefined') return;
  const run = () =>
    void registerServiceWorker({
      container: 'serviceWorker' in navigator ? navigator.serviceWorker : undefined,
      enabled,
      warm: (url) => fetch(url, { cache: 'no-cache' }),
    });
  if (document.readyState === 'complete') run();
  else window.addEventListener('load', run, { once: true });
}
